{"file_path":"scripts/ui/ResultsPanel.gd","new_string":"# ==================== 样式辅助 ====================
func _ui_scale() -> float:
	return UiKit.scale()

# 字号统一走 UiKit 档位（FS_XS..FS_HUGE）× 全局 scale
func _fs(tier: int) -> int:
	return int(round(tier * _ui_scale()))

func _apply_label_style(label: Label, font_size: int = 16, color: Color = UiKit.C_TEXT):
	label.add_theme_font_size_override("font_size", int(round(font_size * _ui_scale())))
	label.add_theme_color_override("font_color", color)
	label.add_theme_color_override("font_outline_color", Color.BLACK)
	label.add_theme_constant_override("outline_size", 1)

func _apply_panel_style(panel: Panel, alpha: float = 0.8):
	panel.add_theme_stylebox_override("panel",
		UiKit.flat(alpha, 0, 0, Color.TRANSPARENT, Color(0, 0, 0, alpha), 0.0))","old_string":"# ==================== 样式辅助 ====================
func _ui_scale() -> float:
	var vp := get_viewport()
	if not vp:
		return 1.7
	var vw := vp.get_visible_rect().size.x
	return clampf(vw / 2400.0, 1.0, 1.2) * 1.7

func _apply_label_style(label: Label, font_size: int = 14, color: Color = Color.WHITE):
	label.add_theme_font_size_override("font_size", int(round(font_size * _ui_scale())))
	label.add_theme_color_override("font_color", color)
	label.add_theme_color_override("font_outline_color", Color.BLACK)
	label.add_theme_constant_override("outline_size", 1)

func _apply_panel_style(panel: Panel, alpha: float = 0.8):
	var style = StyleBoxFlat.new()
	style.bg_color = Color(0, 0, 0, alpha)
	panel.add_theme_stylebox_override("panel", style)"}

