## 临时探针（跑完删除）：验证 BulletVisual 技能弹按 Q/W/R 槽位分形状的 vkind 编码/解码对称性。

const OLD_VKIND_BASE := 100
const OLD_VKIND_MUL := 16

var _ok := true


func _ready() -> void:
	var heroes := ["妲己", "吕布", "后羿", "甄姬", "小乔", "马超", "东皇太一", "狄仁杰", "孙尚香", "马可波罗"]
	for h in heroes:
		var hero := Hero.new()
		hero.display_name = h
		hero.attack_range = 800.0
		hero.team = 0
		var vks: Array = []
		var shapes: Array = []
		var sizes: Array = []
		var sigs: Array = []
		for slot in range(3):
			var b := Bullet.new()
			b.source = hero
			b.team = 0
			b.skill_id = slot + 1
			var spec := BulletVisual.spec_for(b)
			var vk := BulletVisual.vkind_for(b)
			var dec := BulletVisual.decode_vkind(vk)
			var node := BulletVisual.build_from_vkind(vk)
			var sig := _sig(node)
			node.free()
			print("%s slot=%d skill_id=%d vk=%d spec_shape=%d dec_shape=%d dec_slot=%d dec_size=%.4f spec_size=%.4f node=%s" % [
				h, slot, slot + 1, vk, int(spec["shape"]), int(dec["shape"]), int(dec["slot"]),
				float(dec["size"]), float(spec["size_mult"]), sig])
			vks.append(vk)
			shapes.append(int(dec["shape"]))
			sizes.append(float(spec["size_mult"]))
			sigs.append(sig)
			if int(dec["shape"]) != int(spec["shape"]):
				_ok = false
				print("  !! decode shape mismatch")
			if not is_equal_approx(float(dec["size"]), float(spec["size_mult"])):
				_ok = false
				print("  !! decode size mismatch")
			if int(dec["slot"]) != slot:
				_ok = false
				print("  !! decode slot mismatch")
			if vk < 100 or vk >= 1000:
				_ok = false
				print("  !! vk out of custom range")
		var d_vk := _distinct(vks)
		var d_shape := _distinct(shapes)
		var d_node := _distinct(sigs)
		var r_bigger := sizes[2] > sizes[0] and sizes[2] > sizes[1]
		print("%s VK_DISTINCT=%s SHAPE_DISTINCT=%s NODE_DISTINCT=%s ULT_BIGGER=%s vk=%s shapes=%s" % [
			h, d_vk, d_shape, d_node, r_bigger, vks, shapes])
		_ok = _ok and d_vk and d_shape and d_node and r_bigger
		hero.free()

	# 普攻弹：vkind 应与旧公式完全一致（100 + shape*16 + palette）
	var ranged := Hero.new()
	ranged.display_name = "后羿"
	ranged.attack_range = 800.0
	ranged.team = 0
	for tid in [0, 1]:
		var aa := Bullet.new()
		aa.source = ranged
		aa.team = tid
		aa.skill_id = 0
		var aa_spec := BulletVisual.spec_for(aa)
		var aa_vk := BulletVisual.vkind_for(aa)
		var old_vk := OLD_VKIND_BASE + int(aa_spec["shape"]) * OLD_VKIND_MUL + int(aa_spec["palette"])
		var aa_dec := BulletVisual.decode_vkind(aa_vk)
		print("AA team=%d vk=%d old_vk=%d equal=%s shape=%d palette=%d dec_shape=%d dec_slot=%d size=%.3f" % [
			tid, aa_vk, old_vk, aa_vk == old_vk, int(aa_spec["shape"]), int(aa_spec["palette"]),
			int(aa_dec["shape"]), int(aa_dec["slot"]), float(aa_dec["size"])])
		_ok = _ok and aa_vk == old_vk and int(aa_dec["shape"]) == int(aa_spec["shape"])
	# 近战英雄普攻 = 旧行为（不出弹：vkind 0）
	var melee := Hero.new()
	melee.display_name = "亚瑟"
	melee.attack_range = 200.0
	melee.team = 0
	var mb := Bullet.new()
	mb.source = melee
	mb.team = 0
	mb.skill_id = 0
	print("MELEE_AA vk=", BulletVisual.vkind_for(mb))
	_ok = _ok and BulletVisual.vkind_for(mb) == 0
	# 技能弹连续 slot 的 vk 递增关系（slot0→slot1→slot2 每档 +12*16）
	var h2 := Hero.new()
	h2.display_name = "妲己"
	h2.attack_range = 800.0
	h2.team = 0
	var seq: Array = []
	for slot in range(3):
		var bb := Bullet.new()
		bb.source = h2
		bb.team = 0
		bb.skill_id = slot + 1
		seq.append(BulletVisual.vkind_for(bb))
	print("STEP 妲己 vk=", seq, " diffs=", [seq[1] - seq[0], seq[2] - seq[1]])
	_ok = _ok and seq[1] - seq[0] == 12 * 16 and seq[2] - seq[1] == 12 * 16
	print("ASSERT_ALL_OK=", _ok)
	get_tree().quit()


func _distinct(arr: Array) -> bool:
	return arr.size() == 3 and arr[0] != arr[1] and arr[1] != arr[2] and arr[0] != arr[2]


func _sig(n: Node) -> String:
	var parts: Array = []
	for c in n.get_children():
		if c is MeshInstance3D:
			var mi: MeshInstance3D = c
			var mc := "null"
			if mi.mesh != null:
				mc = mi.mesh.get_class()
			parts.append("%s|%.2f,%.2f,%.2f|%.2f,%.2f,%.2f|%.2f,%.2f,%.2f" % [
				mc, mi.scale.x, mi.scale.y, mi.scale.z,
				mi.position.x, mi.position.y, mi.position.z,
				mi.rotation.x, mi.rotation.y, mi.rotation.z])
		var sub := _sig(c)
		if sub != "":
			parts.append(sub)
	return ";".join(PackedStringArray(parts))
","file_path":"scripts/dev/_bv_probe.gd"}

