func _distinct(arr: Array) -> bool:
	return arr.size() == 3 and arr[0] != arr[1] and arr[1] != arr[2] and arr[0] != arr[2]


func _sig(n: Node) -> String:
	var parts: Array = []
	for c in n.get_children():
		if c is MeshInstance3D:
			var mi: MeshInstance3D = c
			var mc := "null"
			if mi.mesh != null:
				mc = mi.mesh.get_class()
			parts.append("%s|%.2f,%.2f,%.2f|%.2f,%.2f,%.2f|%.2f,%.2f,%.2f" % [
				mc, mi.scale.x, mi.scale.y, mi.scale.z,
				mi.position.x, mi.position.y, mi.position.z,
				mi.rotation.x, mi.rotation.y, mi.rotation.z])
		var sub := _sig(c)
		if sub != "":
			parts.append(sub)
	return ";".join(PackedStringArray(parts))
